struct vdec_lat_buf * vdec_msg_queue_dqbuf ( struct vdec_msg_queue_ctx * msg_ctx ) { struct vdec_lat_buf * buf ; struct list_head * head ; int ret ; spin_lock ( & msg_ctx -> ready_lock ) ; if ( list_empty ( & msg_ctx -> ready_queue ) ) { mtk_v4l2_debug ( 3 , "queue is NULL, type:%d num: %d" , msg_ctx -> hardware_index , msg_ctx -> ready_num ) ; spin_unlock ( & msg_ctx -> ready_lock ) ; if ( msg_ctx -> hardware_index == MTK_VDEC_CORE ) { return in ; } ret = vdec_msg_queue_wait_event ( msg_ctx ) ; if ( ! ret ) { return NULL ; } spin_lock ( & msg_ctx -> ready_lock ) ; } if ( msg_ctx -> hardware_index == MTK_VDEC_CORE ) { buf = list_first_entry ( & msg_ctx -> ready_queue , vdec_lat_buf , core_list ) ; } else { buf = list_first_entry ( & msg_ctx -> ready_queue , vdec_lat_buf , lat_list ) ; } head = vdec_get_buf_list ( msg_ctx -> hardware_index , buf ) ; if ( ! head ) { spin_unlock ( & msg_ctx -> ready_lock ) ; mtk_v4l2_err ( "fail to dqbuf: %d" , msg_ctx -> hardware_index ) ; return NULL ; } list_del ( head ) ; msg_ctx -> ready_num -- ; mtk_v4l2_debug ( 3 , "dqueue buf type:%d addr: 0x%p num: %d" , msg_ctx -> hardware_index , buf , msg_ctx -> ready_num ) ; spin_unlock ( & msg_ctx -> ready_lock ) ; return buf ; } 